function d({registerIndicator:s,nulls:f}){s({id:"oa-vf",name:"Volume Force (VF)",category:"Volume",placement:"pane",inputs:[{key:"length",type:"number",label:"Smoothing Period",default:14,min:1,max:5e3,step:1}],plots:[{key:"vf",type:"line",title:"Volume Force",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],background:({bars:t,values:i})=>t.map((h,n)=>{const l=i.vf[n];return Number.isFinite(l)?l>0?"#26a69a22":"#ef535022":null}),calc(t,i){const n=2/(Math.max(1,Math.floor(Number(i.length)||14))+1),l=new Array(t.length).fill(NaN);let u=!0,r=1,o=0;for(let e=0;e<t.length;e++){const c=t[e].close,a=e>0?t[e-1].close:c,p=Number.isFinite(c)&&Number.isFinite(a)?c-a:0,g=Number.isFinite(t[e].volume)?t[e].volume:0,v=p*g;if(o=n*(v-o)+o,u){r*=1-n;const m=1-r;l[e]=m>0?o/m:o,u=r>1e-10}else l[e]=o}return{vf:f(l)}}})}export{d as default};
